INSERT INTO `whatsapp_messages` VALUES (61,'unknow_keyword',NULL,'Unknow Keyword','unknow keyword','Mohon maaf, keywoard yang anda masukkan salah\n\nKeyword yang tersedia:\n%keywords%','Pesan yang dikirim saat pesan yang diterima tidak ada dalam keyword.',1,0,'2025-01-02 19:32:10','2025-01-02 19:32:10',NULL),(62,'payment',NULL,'Pembayaran Lunas','payment','===============================\r\n      🖥️ *SHANUM NETWORK FIBER*  \r\n       🧾 *Receipt #:* %billing_number%  \r\n===============================\r\nYth. Bpk/Ibu %name%, \r\n*Customer ID:* _%customer_id%_ \r\nBerikut adalah rincian pembayaran Anda:  \r\n\r\n🔹 *Detail Paket:*  \r\n*📦 Paket:* _%paket%_  \r\n*📆 Periode:* _%periode%_  \r\n*💶 Harga Paket:* _%bill%_  \r\n\r\n🔹 *Rincian Pembayaran:*  \r\n*💸 Potongan Harga:* _%discount%_  \r\n*🌟 Jenis Potongan:* _%member%_\r\n*💰 Total Bayar:* *_%total%_*  \r\n  \r\n🔹 *Informasi Pembayaran:*  \r\n*👨‍💼 Teller:* _%teller%_  \r\n*🗓️ Tanggal:* _%payment_time%_  \r\n*💳 Metode Pembayaran:* _%payment_methode%_  \r\n\r\n ==========[ *L U N A S* ]========== \r\n🙏 Terima kasih telah mempercayakan \r\nkebutuhan internet Anda kepada kami.  \r\n💡 Kami berkomitmen untuk selalu \r\nmemberikan pelayanan terbaik.  \r\n===============================  \r\n🏢 *Shanum Network Fiber*  \r\n🗺️ Jl. Sukamaju No. 49 RT 009/007  \r\n   Ciseureuh, Purwakarta \r\n   \r\n_Pwrd by PT. Global Sarana Elektronika_  \r\n===============================','Pesan yang dikirim saat pelanggan melakukan pembayaran.',1,0,'2025-01-02 19:32:10','2025-04-04 13:30:44',NULL),(63,'unknow_customer',NULL,'Non Customer','unknow customer','Mohon maaf, anda belum terdaftar sebagai customer kami.\r\nSilahkan menghubungi 0856-4233-6774 untuk proses registrasi.','Pesan yang dikirim bukan customer.',1,0,'2025-01-02 19:32:10','2025-02-08 15:55:36',NULL),(64,'unpayment',NULL,'Unpayment','unpayment','Yth. Bpk/Ibu %name%,\r\n%address%\r\nCustomer ID: %customer_id%\r\n\r\nMaaf telah terjadi kesalahan system.\r\n\r\nPembayaran anda:\r\nNomor Tagihan: *%billing_number%*\r\nJumlah: *%bill%*\r\n\r\nTelah dibatalkan.\r\n\r\nTerima kasih telah menggunakan layanan internet kami.\r\n\r\n*Shanum Network Fiber*\r\nJl. Sukamaju No. 49 RT 009/007\r\nCiseureuh, Purwakarta\r\n\r\n*_Pesan ini dikirim secara otomatis oleh sistem, harap tidak membalas pesan ini._*','Pesan yang dikirim saat admin melakukan pembatalan pembayaran.',1,0,'2025-01-02 19:32:10','2025-03-05 20:56:19',NULL),(65,'no_paket',NULL,'Customer Dont Have Paket','no paket','Yth. Bpk/Ibu %name%,\r\n%address%\r\nCustomer ID: %customer_id%\r\n\r\nSaat ini anda sudah terdaftar di sistem kami, namun belum mempunyai paket.\r\n\r\nJika anda ingin menggunakan layanan kami, silahkan hubungi 0856-4233-6774.\r\n\r\n*Shanum Network Fiber*\r\nJl. Sukamaju No. 49 RT 009/007\r\nCiseureuh, Purwakarta\r\n\r\n*Pesan ini dikirim secara otomatis oleh sistem, harap tidak membalas pesan ini.*','Pesan yang dikirim saat pelanggan tidak memiliki paket internet.',1,0,'2025-01-02 19:32:10','2025-02-08 15:53:57',NULL),(66,'no_bill',NULL,'No Bill','no bill','Yth. Bpk/Ibu %name%,\n%address%\nCustomer ID: %customer_id%\n\nSaat ini anda belum memiliki tagihan.\n\nKami mengucapkan terima kasih karena anda tertib administrasi.\nIni sangat berguna untuk kemajuan kami dalam memperbaiki layanan.\n\n*Shanum Network Fiber*\nJl. Sukamaju No. 49 RT 009/007\nCiseureuh, Purwakarta\n\n*Pesan ini dikirim secara otomatis oleh sistem, harap tidak membalas pesan ini.*','Pesan yang dikirim saat pelanggan tidak memiliki tagihan.',1,0,'2025-01-02 19:32:10','2025-01-02 19:32:10',NULL),(67,'reminder_bill',NULL,'Reminder Bill','warning bill','Yth. Bpk/Ibu %name%,\r\n%address%\r\nCustomer ID: %customer_id%\r\n\r\nDalam %day% hari, batas akhir pembayaran paket internet Anda akan tiba. Saat ini, Anda memiliki %count-bill% tagihan yang belum dibayar:\r\n\r\n%pakets%\r\n*💰 Total tagihan:* %total-bill%\r\n\r\nLakukan pembayaran sebelum jatuh tempo untuk menghindari isolir otomatis oleh system kami.\r\n\r\n💳 Anda dapat melakukan pembayaran melalui Admin kami:\r\n🔹 *_Area Purwakarta (a.n Dian Ardiansyah)_*\r\n    ▫ BCA : 2990407315\r\n    ▫ Mandiri : 1730012695905\r\n    ▫ DANA : 085795909904\r\n\r\n🔹 *_Area Babakancikao (a.n Budi Kosasih)_*\r\n    ▫ Mandiri : 1730012656030\r\n    ▫ DANA : 085710840198\r\n\r\n📌 Silakan informasikan kepada kami jika Anda sudah melakukan pembayaran melalui _WhatsApp Admin_\r\n\r\nTerima kasih telah menggunakan layanan internet kami.\r\n\r\n*Shanum Network Fiber*\r\n📍 Jl. Sukamaju No. 49 RT 009/007, Ciseureuh, Purwakarta\r\n\r\n📩 *_Pesan ini dikirim secara otomatis oleh sistem, harap tidak membalas pesan ini._*','Pesan yang dikirim untuk memberitahukan bahwa tagihan mereka akan jatuh tempo.',1,0,'2025-01-02 19:32:10','2025-03-10 10:25:13',NULL),(68,'deadline_bill',NULL,'Deadline Bill','warning bill','Yth. Bpk/Ibu %name%,\r\n%address%\r\nCustomer ID: %customer_id%\r\n\r\nHari ini adalah batas akhir pembayaran paket internet Anda. Anda memiliki %count-bill% tagihan yang belum dibayar:\r\n\r\n%pakets%\r\n*💰 Total tagihan:* %total-bill%\r\n\r\nSegera lakukan pembayaran sebelum jatuh tempo untuk menghindari isolir otomatis oleh system kami.\r\n\r\n💳 Anda dapat melakukan pembayaran melalui Admin kami:\r\n🔹 *_Area Purwakarta (a.n Dian Ardiansyah)_*\r\n    ▫ BCA : 2990407315\r\n    ▫ Mandiri : 1730012695905\r\n    ▫ DANA : 085795909904\r\n\r\n🔹 *_Area Babakancikao (a.n Budi Kosasih)_*\r\n    ▫ Mandiri : 1730012656030\r\n    ▫ DANA : 085710840198\r\n\r\n📌 Silakan informasikan kepada kami jika Anda sudah melakukan pembayaran melalui _WhatsApp Admin_\r\n\r\nTerima kasih telah menggunakan layanan internet kami.\r\n\r\n*Shanum Network Fiber*\r\n📍 Jl. Sukamaju No. 49 RT 009/007, Ciseureuh, Purwakarta\r\n\r\n📩 *_Pesan ini dikirim secara otomatis oleh sistem, harap tidak membalas pesan ini._*','Pesan yang dikirim untuk memberitahukan bahwa tagihan mereka sudah jatuh tempo.',1,0,'2025-01-02 19:32:10','2025-03-10 10:26:18',NULL),(69,'past_due_warning',NULL,'Past Due Warning','warning bill','Yth. Bpk/Ibu %name%,\r\n%address%\r\nCustomer ID: %customer_id%\r\n\r\nKami ingin mengingatkan bahwa Anda memiliki %count-bill% tagihan paket internet yang belum dibayar dan telah melewati jatuh tempo.\r\nBerikut adalah rincian tagihan Anda:\r\n\r\n%pakets%\r\n*💰 Total tagihan:* %total-bill%\r\n\r\nMohon segera melakukan pembayaran untuk menghindari gangguan layanan.\r\n\r\n💳 Anda dapat melakukan pembayaran melalui Admin kami:\r\n🔹 *_Area Purwakarta (a.n Dian Ardiansyah)_*\r\n    ▫ BCA : 2990407315\r\n    ▫ Mandiri : 1730012695905\r\n    ▫ DANA : 085795909904\r\n\r\n🔹 *_Area Babakancikao (a.n Budi Kosasih)_*\r\n    ▫ Mandiri : 1730012656030\r\n    ▫ DANA : 085710840198\r\n\r\n📌 Silakan informasikan kepada kami jika Anda sudah melakukan pembayaran melalui _WhatsApp Admin_\r\n\r\nKami berkomitmen untuk memberikan layanan terbaik bagi Anda.\r\n\r\n*Shanum Network Fiber*\r\n📍 Jl. Sukamaju No. 49 RT 009/007, Ciseureuh, Purwakarta\r\n\r\n📩 *_Pesan ini dikirim secara otomatis oleh sistem, harap tidak membalas pesan ini._*','Pesan yang dikirim untuk mengingatkan bahwa tagihan sudah melewati jatuh tempo.',1,0,'2025-01-02 19:32:11','2025-03-10 10:26:41',NULL),(70,'info_tagihan',NULL,'Info Tagihan','info tagihan','Yth. Bpk/Ibu %name%,\n%address%\nCustomer ID: %customer_id%\n\nBerikut info tagihan anda.\n%bills%\nJumlah tagihan: %total-bills%\n\nAnda dapat melakukan pembayaran melalui:\n%account-banks%\n\nTerima kasih telah mempercayakan kebutuhan internet anda kepada kami.\n\n*Shanum Network Fiber*\nJl. Sukamaju No. 49 RT 009/007\nCiseureuh, Purwakarta\n\n*_Pesan ini dikirim secara otomatis oleh sistem, harap tidak membalas pesan ini._*','Pesan yang dikirim saat pelanggan melakukan pengecekan tagihan.',0,0,'2025-01-02 19:32:11','2025-01-02 19:32:11',NULL),(71,'info_paket',NULL,'Info Paket','info paket','Yth. Bpk/Ibu %name%,\n%address%\nCustomer ID: %customer_id%\n\nBerikut kami sampaikan rincian paket anda:\n%pakets%\n\nTerima kasih telah mempercayakan layanan internet anda kepada kami. Kami berkomitmen untuk selalu memberikan pelayanan yang terbaik.\n\n*Shanum Network Fiber*\nJl. Sukamaju No. 49 RT 009/007\nCiseureuh, Purwakarta\n\n*_Pesan ini dikirim secara otomatis oleh sistem, harap tidak membalas pesan ini._*','Pesan yang dikirim saat pelanggan melakukan pengecekan paket.',0,0,'2025-01-02 19:32:11','2025-01-02 19:32:11',NULL),(72,'disable_paket',NULL,'Disable Paket','disable paket','Yth. Bpk/Ibu %name%,\n%address%\nCustomer ID: %customer_id%\n\nPaket anda sudah dinon-aktifkan, kami tidak mengenakan biaya layanan selama paket anda dinon-aktifkan.\n\nInfo paket:\nPaket: *%paket_name%*\nStatus: *%status%*\n\n*Shanum Network Fiber*\nJl. Sukamaju No. 49 RT 009/007\nCiseureuh, Purwakarta\n\n*_Pesan ini dikirim secara otomatis oleh sistem, harap tidak membalas pesan ini._*','Pesan yang dikirim saat paket di non-aktifkan.',1,0,'2025-01-02 19:32:11','2025-01-02 19:32:11',NULL),(73,'enable_paket',NULL,'Enable Paket','disable paket','Yth. Bpk/Ibu %name%,\n%address%\nCustomer ID: %customer_id%\n\nPaket anda sudah diaktifkan, selamat menikmati layanan internet kami kembali.\n\nInfo paket:\nPaket: *%paket_name%*\nTagihan: *%bill%* per bulan\nStatus: *%status%*\nTanggal Aktivasi : %activation_date%\n\n*Shanum Network Fiber*\nJl. Sukamaju No. 49 RT 009/007\nCiseureuh, Purwakarta\n\n*_Pesan ini dikirim secara otomatis oleh sistem, harap tidak membalas pesan ini._*','Pesan yang dikirim saat paket di aktifkan.',1,0,'2025-01-02 19:32:11','2025-01-02 19:32:11',NULL),(74,'activation_paket',NULL,'Activation Paket','activation paket','Yth. Bpk/Ibu %name%,\n%address%\nCustomer ID: %customer_id%\n\nPaket anda sudah berhasil diaktivasi, selamat menikmati layanan internet dari kami.\n\nMasa berlaku: %periode%\nBatas bayar: Setiap tanggal %deadline%\nNama CS: %cs_name%\nContact: %cs_contact%\n\nJika terjadi kendala pada jaringan, silahkan hubungi CS kami.\n\n*Shanum Network Fiber*\nJl. Sukamaju No. 49 RT 009/007\nCiseureuh, Purwakarta\n\n*_Pesan ini dikirim secara otomatis oleh sistem, harap tidak membalas pesan ini._*','Pesan yang dikirim saat aktivasi paket.',1,0,'2025-01-02 19:32:11','2025-01-02 19:32:11',NULL),(75,'add_paket',NULL,'Add Paket','add paket','Yth. Bpk/Ibu %name%,\n%address%\nCustomer ID: %customer_id%\n\nPendaftaran paket berhasil, berikut info layanan paket anda:\n\nPaket: %paket_name%\nHarga: %paket_price%\n\nBiaya Langganan: %bill% per bulan\n\nsilahkan tunggu beberapa saat karna paket anda masih dalam proses aktivasi.\n\n*Shanum Network Fiber*\nJl. Sukamaju No. 49 RT 009/007\nCiseureuh, Purwakarta\n\n*Pesan ini dikirim secara otomatis oleh sistem, harap tidak membalas pesan ini.*','Pesan yang dikirim saat penambahan paket customer.',1,0,'2025-01-02 19:32:11','2025-01-02 19:32:11',NULL),(76,'deactivation_customer',NULL,'Deactivation Customer','deactivation customer','Yth. Bpk/Ibu %name%,\n%address%\nCustomer ID: %customer_id%\n\nDengan berat hati kami menonaktifkan akun anda. Jika tidak keberatan, silahkan kirim masukkan anda untuk perbaikan pada layanan kami.\n\nTerima kasih telah menjadi pelanggan kami selama ini.\n\n*Shanum Network Fiber*\nJl. Sukamaju No. 49 RT 009/007\nCiseureuh, Purwakarta\n\n*_Pesan ini dikirim secara otomatis oleh sistem, harap tidak membalas pesan ini._**','Pesan yang dikirim saat customer di non-aktifkan.',1,0,'2025-01-02 19:32:11','2025-01-02 19:32:11',NULL),(77,'activation_customer',NULL,'Activation Customer','activation customer','Yth. Bpk/Ibu %name%,\r\nAktivasi akun berhasil. Berikut detail informasi akun anda:\r\n\r\n🔹 *Data Pelanggan:*  \r\n*👥 Nama:* _%name%_  \r\n*🆔 Customer ID:* _%customer_id%_  \r\n*📧 Email:* _%email%_\r\n*📍 Alamat:* _%address%_\r\n\r\n🔹 *Detail Paket:*  \r\n*📦 Paket:* _%paket%_  \r\n*💶 Harga Paket:* _%bill%_  \r\n\r\n🔹 *Admin Area:*\r\n*👨🏼‍💼 Name:* _%admin%_\r\n*📲 Phone:* %customer_service%\r\n\r\nSimpan informasi ini untuk pengajuan layanan atau saat terjadi gangguan layanan.\r\n\r\n===============================  \r\n🏢 *Shanum Network Fiber*  \r\n🗺️ Jl. Sukamaju No. 49 RT 009/007  \r\n   Ciseureuh, Purwakarta \r\n\r\n_Pwrd by PT. Global Sarana Elektronika_ \r\n===============================\r\n*_Pesan ini dikirim secara otomatis oleh sistem, harap tidak membalas pesan ini._*','Pesan yang dikirim saat aktivasi customer.',1,0,'2025-01-02 19:32:11','2025-03-14 20:12:28',NULL),(78,'register_customer',NULL,'Register Customer','register customer','Yth. Bpk/Ibu %name%,\r\n%address%\r\n\r\nTerima kasih telah melakukan pendaftaran di sistem kami.\r\nBerikut layanan yang anda pilih:\r\n\r\n%pakets%\r\n\r\nJika anda ingin menggunakan layanan kami, silahkan hubungi *WA0856-4233-6774*.\r\n\r\n*Shanum Network Fiber*\r\nJl. Sukamaju No. 49 RT 009/007\r\nCiseureuh, Purwakarta\r\n\r\n*_Pesan ini dikirim secara otomatis oleh sistem, harap tidak membalas pesan ini._*','Pesan yang dikirim saat registrasi customer.',1,0,'2025-01-02 19:32:11','2025-02-08 15:56:39',NULL),(79,'create_new_bill',NULL,'Create New bill','create new bill','===============================\r\n📢 *Informasi Tagihan Internet Anda*  \r\n===============================\r\n\r\nYth. Bpk/Ibu %name%  \r\n%address%  \r\n*🆔 Customer ID:* _%customer_id%_  \r\n\r\nSaat ini, Anda sudah dapat melakukan pembayaran tagihan internet. Berikut rincian tagihan Anda:  \r\n\r\n🔹 *Detail Paket:*  \r\n%pakets%\r\n*💰 Total Tagihan:* *_%total-bill%_*\r\n*🚨 Jatuh Tempo:* _%deadline%_    \r\n*👨🏼‍🔧 Admin:* _%admin%_  \r\n\r\n🔹 *Rekening Pembayaran:*  \r\n🏠 *Area Purwakarta* (a.n Dian Ardiansyah)  \r\n   ▫️ *BCA:* 2990407315  \r\n   ▫️ *Mandiri:* 1730012695905  \r\n   ▫️ *DANA:* 085795909904  \r\n\r\n🏠 *Area Babakancikao* (a.n Budi Kosasih)  \r\n   ▫️ *Mandiri:* 1730012656030  \r\n   ▫️ *DANA:* 085710840198  \r\n\r\n🔹 *Konfirmasi Pembayaran:*  \r\n📲 Harap konfirmasi ke WhatsApp Admin  \r\n\r\n===============================\r\n🌐 Cek status tagihan Anda dengan login ke: shanetfiber.my.id\r\n🔑 *Username:* _No HP terdaftar_  \r\n🔑 *Password:* _12345678_  \r\n\r\n🙏 Terima kasih telah mempercayakan kebutuhan internet Anda kepada kami.  \r\n===============================\r\n🏢 *Shanum Network Fiber*  \r\n🗺️ Jl. Sukamaju No. 49 RT 009/007  \r\n   Ciseureuh, Purwakarta  \r\n\r\n_Pwrd by PT Global Sarana Elektronika_\r\n===============================\r\n📩 _Pesan ini dikirim secara otomatis oleh sistem. Harap tidak membalas pesan ini_  \r\n===============================','Pesan yang dikirim saat tagihan dibuat.',1,0,'2025-01-02 19:32:11','2025-04-01 11:52:20',NULL),(80,'paylater',NULL,'Pay Later','paylater','===============================\r\n        🖥️ *SHANUM NETWORK FIBER*  \r\n         🧾 *Receipt #:* %billing_number%  \r\n=============================== \r\nYth. Bpk/Ibu %name%,\r\n*Cust - ID:* _%customer_id%_  \r\nBerikut kami sampaikan detail pembayaran mundur Anda:\r\n\r\n🔹 *Detail Paket:* \r\n*📦 Paket:* _%paket%_\r\n*📆 Periode:* _%periode%_\r\n*💶 Harga Paket:* *_%bill%_*\r\n\r\n🔹 *Rincian Pembayaran:*  \r\n*💸 Potongan Harga:* _%discount%_  \r\n*🌟 Jenis Potongan:* _%member%_ \r\n*💰 Total Dibayarkan:* *_%total%_*  \r\n\r\n🔹 *Informasi Pembayaran:*  \r\n*👨‍💼 Teller:* _%teller%_  \r\n*💳 Metode Pembayaran:* _%payment_methode%_\r\n*🗓️ Jatuh Tempo:* *%paylater%*\r\n\r\n========[ *P A Y   L E T E R* ]========\r\nMohon dapat membayar tagihan tepat \r\nwaktu guna menghindari terisolirnya \r\nakun Anda, \r\n                🙏 Terima Kasih 🙏\r\n===============================\r\n🏢 *Shanum Network Fiber*  \r\n🗺️ Jl. Sukamaju No. 49 RT 009/007  \r\n   Ciseureuh, Purwakarta \r\n\r\n_Pwrd by PT. Global Sarana Elektronika_ \r\n===============================','Pesan yang dikirim saat permintaan pay later.',1,0,'2025-01-02 19:32:11','2025-03-19 15:07:59',NULL);
